use unisphere_core::*;
fn main(){
 let source=SnapshotRef{path:"/explicit/test.json".into(),format:SnapshotFormat::JsonDocument,session_id:None};
 let snapshot=NativeSnapshot{source:source.clone(),revision:"digest".into(),records:vec![SnapshotRecord{key:"document".into(),bytes:b"{}".to_vec()}]};
 assert!(snapshot.validate(SnapshotLimits{max_records:1,max_record_bytes:2,max_snapshot_bytes:10}).is_ok());
 assert_eq!(snapshot.validate(SnapshotLimits{max_records:1,max_record_bytes:2,max_snapshot_bytes:9}).unwrap_err().kind(),PipelineErrorKind::BatchLimit);
 assert_eq!(snapshot.validate(SnapshotLimits{max_records:1,max_record_bytes:1,max_snapshot_bytes:10}).unwrap_err().kind(),PipelineErrorKind::RecordLimit);
 let mut unsafe_source=source;unsafe_source.format=SnapshotFormat::SqliteKeyValue{table:"table;DROP".into()};assert_eq!(unsafe_source.validate().unwrap_err().kind(),PipelineErrorKind::InvalidInput);
 println!("snapshot contract: exact key+byte aggregate boundary, per-record limit and invalid table rejection passed");
}
